-- Additive knowledge workspace. Public retrieval unifies these reviewed explanations with existing editorial data.
create table public.knowledge_settings(id boolean primary key default true check(id),enabled boolean not null default true,daily_limit integer not null default 60 check(daily_limit between 1 and 60),minute_limit integer not null default 6 check(minute_limit between 1 and 6),external_enabled boolean not null default false,detail text not null default 'concise' check(detail in('concise','extended')),epoch integer not null default 1,updated_at timestamptz not null default now());
insert into public.knowledge_settings(id) values(true);
create table public.knowledge_drafts(id uuid primary key default gen_random_uuid(),payload jsonb not null check(pg_column_size(payload)<16000),version integer not null default 1,published_revision integer,archived boolean not null default false,updated_by uuid references auth.users(id) on delete set null,updated_at timestamptz not null default now());
create table public.knowledge_revisions(id uuid not null references public.knowledge_drafts(id),version integer not null,payload jsonb not null,action text not null check(action in('draft','publish','withdraw','archive','restore')),actor_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),primary key(id,version));
create table private.knowledge_usage(user_id uuid references auth.users(id) on delete cascade,day date not null,minute timestamptz not null,requests integer not null default 0,minute_requests integer not null default 0,primary key(user_id,day));
create table public.knowledge_diagnostics(id bigint generated always as identity primary key,kind text not null check(kind in('missing','provider_failure','served')),topic text not null check(length(topic)<=200),created_at timestamptz not null default now());
create index knowledge_diag_time on public.knowledge_diagnostics(created_at);
create index knowledge_draft_subject on public.knowledge_drafts((payload->>'subject'));
alter table public.knowledge_settings enable row level security;
alter table public.knowledge_drafts enable row level security;
alter table public.knowledge_revisions enable row level security;
alter table public.knowledge_diagnostics enable row level security;
revoke all on public.knowledge_settings,public.knowledge_drafts,public.knowledge_revisions,public.knowledge_diagnostics from public,anon,authenticated;
grant select on public.knowledge_settings to anon,authenticated;
create policy knowledge_status on public.knowledge_settings for select using(true);
grant select on public.knowledge_drafts,public.knowledge_revisions,public.knowledge_diagnostics to authenticated;
create policy knowledge_admin_drafts on public.knowledge_drafts for select to authenticated using((select public.is_admin()));
create policy knowledge_admin_revisions on public.knowledge_revisions for select to authenticated using((select public.is_admin()));
create policy knowledge_admin_diagnostics on public.knowledge_diagnostics for select to authenticated using((select public.is_admin()));
create function private.validate_knowledge(p jsonb,p_publish boolean) returns void language plpgsql set search_path='' as $$
declare s jsonb; k text;begin
 if jsonb_typeof(p)<>'object' or pg_column_size(p)>16000 or (select count(*) from jsonb_object_keys(p))<>16 or exists(select 1 from jsonb_each(p) v where v.value='null'::jsonb) then raise exception 'kyrven: conteúdo inválido';end if;
 for k in select jsonb_object_keys(p) loop if k<>all(array['subject','title','category','body','aliases','mode','scope','season','version','region','evidence','verified_at','valid_until','sources','limitations','related']) then raise exception 'kyrven: campo não autorizado';end if;end loop;
 if p->>'subject' !~ '^[a-z0-9][a-z0-9-]{1,99}$' or coalesce(length(p->>'title'),0) not between 3 and 200 or coalesce(length(p->>'body'),0) not between 20 and 3000 or coalesce(length(p->>'category'),0) not between 3 and 100 or coalesce(length(p->>'limitations'),0) not between 3 and 1000 or coalesce(p->>'mode','') not in('build','zero','both') or coalesce(p->>'scope','') not in('concept','season') or coalesce(p->>'evidence','') not in('official','professional','analysis','editorial','administrator','unconfirmed') then raise exception 'kyrven: revise conteúdo e classificação';end if;
 if jsonb_typeof(p->'sources')<>'array' or jsonb_array_length(p->'sources')>8 or jsonb_typeof(p->'aliases')<>'array' or jsonb_array_length(p->'aliases')>20 or jsonb_typeof(p->'related')<>'array' or jsonb_array_length(p->'related')>8 then raise exception 'kyrven: listas inválidas';end if;
 if coalesce(length(p->>'season'),999)>100 or coalesce(length(p->>'version'),999)>100 or coalesce(length(p->>'region'),999)>100 then raise exception 'kyrven: contexto inválido';end if;
 if p->>'scope'='concept' and (p->>'season'<>'' or p->>'version'<>'') then raise exception 'kyrven: conceito não deve declarar temporada';end if;
 if not isfinite((p->>'verified_at')::timestamptz) or not isfinite((p->>'valid_until')::timestamptz) or (p->>'verified_at')::timestamptz>now()+interval '1 second' or (p->>'valid_until')::timestamptz<=(p->>'verified_at')::timestamptz then raise exception 'kyrven: datas inválidas';end if;
 for s in select value from jsonb_array_elements(p->'aliases') loop if jsonb_typeof(s)<>'string' or length(s#>>'{}') not between 2 and 100 then raise exception 'kyrven: alias inválido';end if;end loop;
 for s in select value from jsonb_array_elements(p->'related') loop if coalesce(s->>'path','') !~ '^/(academy|library|competitive)(/[^[:space:]?#]*)?$' or coalesce(length(s->>'title'),0) not between 3 and 100 then raise exception 'kyrven: link interno inválido';end if;end loop;
 for s in select value from jsonb_array_elements(p->'sources') loop
 if coalesce(s->>'url','') !~ '^https://[^/@[:space:]]+(/[^[:space:]]*)?$' or length(s->>'url')>1500 or s->>'url' ~ '^https://(localhost|127\.|10\.|192\.168\.|169\.254\.|\[)' or coalesce(length(s->>'title'),0) not between 3 and 200 or coalesce(s->>'kind','') not in('official','professional','analysis','editorial','administrator') then raise exception 'kyrven: fonte inválida';end if;
 if s->>'published_on' is not null then perform (s->>'published_on')::date;end if;
 end loop;
 if p_publish then
 if p->>'scope'='season' and coalesce(p->>'season','')='' then raise exception 'kyrven: informe a temporada';end if;
 if p->>'evidence'='unconfirmed' or jsonb_array_length(p->'sources')=0 or (p->>'valid_until')::timestamptz<=now() then raise exception 'kyrven: publicação exige fonte, verificação e validade';end if;
 end if;
 if p->>'evidence'='official' and not exists(select 1 from jsonb_array_elements(p->'sources') x where x->>'kind'='official' and x->>'url' ~ '^https://(www\.)?(fortnite\.com|epicgames\.com)/|^https://(dev|communities)\.epicgames\.com/') then raise exception 'kyrven: confirmação oficial exige fonte Epic';end if;
end;$$;
create function public.save_knowledge(p_id uuid,p_expected integer,p_payload jsonb) returns public.knowledge_drafts language plpgsql security definer set search_path='' as $$
declare d public.knowledge_drafts;begin
 if auth.uid() is null or not public.is_admin() then raise exception 'Administrative role required' using errcode='42501';end if;
 perform pg_advisory_xact_lock(242424);perform private.validate_knowledge(p_payload,false);
 if (select count(*) from public.knowledge_revisions where actor_id=auth.uid() and created_at>now()-interval '1 hour')>=120 then raise exception 'kyrven: limite editorial';end if;
 if p_id is null then if p_expected is distinct from 0 then raise exception 'kyrven: versão inválida';end if;insert into public.knowledge_drafts(payload,updated_by) values(p_payload,auth.uid()) returning * into d;
 else select * into d from public.knowledge_drafts where id=p_id for update;if not found or d.version is distinct from p_expected then raise exception 'kyrven: edição concorrente; recarregue';end if;update public.knowledge_drafts set payload=p_payload,version=version+1,archived=false,updated_by=auth.uid(),updated_at=now() where id=p_id returning * into d;end if;
 insert into public.knowledge_revisions values(d.id,d.version,d.payload,'draft',auth.uid(),now());return d;
end;$$;
create function public.manage_knowledge(p_id uuid,p_expected integer,p_action text,p_confirmation text,p_restore integer default null) returns public.knowledge_drafts language plpgsql security definer set search_path='' as $$
declare d public.knowledge_drafts;content jsonb;begin
 if auth.uid() is null or not public.is_admin() then raise exception 'Administrative role required' using errcode='42501';end if;
 if coalesce(p_action,'') not in('publish','withdraw','archive','restore') or p_confirmation is distinct from upper(p_action) then raise exception 'kyrven: confirmação explícita necessária';end if;
 perform pg_advisory_xact_lock(242424);
 select * into d from public.knowledge_drafts where id=p_id for update;if not found or d.version is distinct from p_expected then raise exception 'kyrven: edição concorrente; recarregue';end if;
 if (select count(*) from public.knowledge_revisions where actor_id=auth.uid() and created_at>now()-interval '1 hour')>=120 then raise exception 'kyrven: limite editorial';end if;
 content:=d.payload;
 if p_action='restore' then select payload into content from public.knowledge_revisions where id=d.id and version=p_restore;if not found then raise exception 'kyrven: versão inexistente';end if;end if;
 if p_action='publish' then
 perform private.validate_knowledge(content,true);
 if exists(select 1 from public.knowledge_drafts x join public.knowledge_revisions r on r.id=x.id and r.version=x.published_revision where x.id<>d.id and not x.archived and r.payload->>'subject'=content->>'subject' and r.payload->>'season'=content->>'season' and r.payload->>'mode'=content->>'mode' and r.payload->>'version'=content->>'version') then raise exception 'kyrven: conflito com conhecimento publicado; revise o registro existente';end if;
 if exists(select 1 from public.knowledge_revisions r where r.id=d.id and r.version=d.published_revision and r.payload->>'evidence'='official') and content->>'evidence'<>'official' then raise exception 'kyrven: não substitua silenciosamente uma fonte oficial';end if;
 end if;
 update public.knowledge_drafts set payload=content,version=version+1,published_revision=case when p_action='publish' then version+1 when p_action in('withdraw','archive') then null else published_revision end,archived=p_action='archive',updated_by=auth.uid(),updated_at=now() where id=d.id returning * into d;
 insert into public.knowledge_revisions values(d.id,d.version,d.payload,p_action,auth.uid(),now());
 update public.knowledge_settings set epoch=epoch+1,updated_at=now();return d;
end;$$;
create function public.configure_knowledge(p_enabled boolean,p_daily integer,p_minute integer,p_external boolean,p_detail text) returns public.knowledge_settings language plpgsql security definer set search_path='' as $$
declare r public.knowledge_settings;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrative role required' using errcode='42501';end if;update public.knowledge_settings set enabled=p_enabled,daily_limit=p_daily,minute_limit=p_minute,external_enabled=p_external,detail=p_detail,epoch=epoch+1,updated_at=now() returning * into r;insert into public.meta_editorial_audit(table_name,record_id,actor_id) values('knowledge_settings',r.epoch::text,auth.uid());return r;end;$$;
create function public.reserve_knowledge(p_preview boolean default false) returns void language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();d date:=(now() at time zone 'UTC')::date;m timestamptz:=date_trunc('minute',now());r private.knowledge_usage;s public.knowledge_settings;begin
 if u is null then raise exception 'Authentication required';end if;
 if p_preview and not public.is_admin() then raise exception 'Administrative role required';end if;
 select * into s from public.knowledge_settings;if not s.enabled and not p_preview then raise exception 'kyrven: assistente temporariamente desativado';end if;
 delete from private.knowledge_usage where day<d-30;delete from public.knowledge_diagnostics where created_at<now()-interval '30 days';
 insert into private.knowledge_usage(user_id,day,minute) values(u,d,m) on conflict do nothing;select * into r from private.knowledge_usage where user_id=u and day=d for update;
 if r.requests>=s.daily_limit or (r.minute=m and r.minute_requests>=s.minute_limit) then raise exception 'kyrven: limite de consultas atingido';end if;
 update private.knowledge_usage set requests=requests+1,minute=m,minute_requests=case when r.minute=m then r.minute_requests+1 else 1 end where user_id=u and day=d;
end;$$;
-- Only approved publications, no raw admin messages or private player context.
-- Current claims require a registered game context, not just a recently edited text.
create function private.knowledge_current(p jsonb,p_mode text) returns boolean language sql stable set search_path='' as $$
 select exists(select 1 from public.meta_versions v join public.meta_contexts c on c.version_id=v.id join public.meta_modes m on m.id=c.mode_id where v.season=p->>'season' and (p->>'version'='' or v.patch=p->>'version') and v.released_on<=current_date and (p_mode='both' or case when m.construction then 'build' else 'zero' end=p_mode) and (p->>'mode'='both' or case when m.construction then 'build' else 'zero' end=p->>'mode') and not exists(select 1 from public.meta_contexts newer join public.meta_versions nv on nv.id=newer.version_id where newer.mode_id=c.mode_id and nv.released_on>v.released_on and nv.released_on<=current_date));
$$;
revoke all on function private.knowledge_current(jsonb,text) from public,anon,authenticated;
create function public.retrieve_knowledge(p_query text,p_preview boolean default false,p_mode text default 'both',p_season text default '',p_version text default '',p_region text default '',p_current boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;begin
 if length(p_query) not between 2 and 1500 then raise exception 'Invalid question';end if;
 if p_preview and (auth.uid() is null or not public.is_admin()) then raise exception 'Administrative role required';end if;
 if not p_preview and not (select enabled from public.knowledge_settings) then return '[]';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'revision',version,'payload',payload,'origin','knowledge')),'[]') into result from (
 select d.id,r.version,r.payload from public.knowledge_drafts d join public.knowledge_revisions r on r.id=d.id and r.version=case when p_preview then d.version else d.published_revision end where not d.archived and (p_preview or r.action='publish') and (p_mode='both' or r.payload->>'mode' in('both',p_mode)) and (not p_current or (r.payload->>'scope'='season' and (p_preview or private.knowledge_current(r.payload,p_mode)))) and (r.payload->>'scope'='concept' or (r.payload->>'season'=p_season and (r.payload->>'version'='' or r.payload->>'version'=p_version) and (r.payload->>'region'='' or r.payload->>'region'=p_region))) and exists(select 1 from regexp_split_to_table(p_query,'[[:space:]]+') t where length(t)>=3 and ((r.payload->>'title')||' '||(r.payload->>'body')||' '||(r.payload->'aliases')::text) ilike '%'||replace(replace(t,'%','\%'),'_','\_')||'%') order by ts_rank(to_tsvector('simple',r.payload::text),plainto_tsquery('simple',p_query)) desc,d.id limit 12) x;
 return result;
end;$$;
create function public.knowledge_diagnostic(p_kind text,p_topic text default '') returns void language plpgsql security definer set search_path='' as $$begin if auth.uid() is null or p_kind not in('missing','served','provider_failure') or length(p_topic)>200 then raise exception 'Invalid diagnostic';end if;if not exists(select 1 from private.knowledge_usage where user_id=auth.uid() and day=(now() at time zone 'UTC')::date and minute=date_trunc('minute',now()) and requests>0) then raise exception 'Reservation required';end if;perform pg_advisory_xact_lock(242425);if (select count(*) from public.knowledge_diagnostics where created_at>now()-interval '1 minute')>=500 then return;end if;insert into public.knowledge_diagnostics(kind,topic) values(p_kind,p_topic);end;$$;
create function public.refresh_knowledge() returns integer language plpgsql security definer set search_path='' as $$declare e integer;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrative role required';end if;update public.knowledge_settings set epoch=epoch+1,updated_at=now() returning epoch into e;insert into public.meta_editorial_audit(table_name,record_id,actor_id) values('knowledge_reload',e::text,auth.uid());return e;end;$$;
revoke all on function private.validate_knowledge(jsonb,boolean) from public,anon,authenticated;
revoke all on function public.save_knowledge(uuid,integer,jsonb),public.manage_knowledge(uuid,integer,text,text,integer),public.configure_knowledge(boolean,integer,integer,boolean,text),public.reserve_knowledge(boolean),public.knowledge_diagnostic(text,text),public.refresh_knowledge() from public,anon,authenticated;
grant execute on function public.save_knowledge(uuid,integer,jsonb),public.manage_knowledge(uuid,integer,text,text,integer),public.configure_knowledge(boolean,integer,integer,boolean,text),public.reserve_knowledge(boolean),public.knowledge_diagnostic(text,text),public.refresh_knowledge() to authenticated;
revoke all on function public.retrieve_knowledge(text,boolean,text,text,text,text,boolean) from public;
grant execute on function public.retrieve_knowledge(text,boolean,text,text,text,text,boolean) to anon,authenticated;

insert into public.knowledge_drafts(id,payload,published_revision) values('00000000-0000-4000-8000-000000008800','{"subject": "surge", "title": "Storm Surge", "category": "competitivo", "body": "Storm Surge é um mecanismo relacionado à quantidade de jogadores sobreviventes em determinadas fases da tempestade. Quando a condição de população se aplica, jogadores abaixo de um limite de dano causado podem receber dano periódico até a população ficar dentro do limite. Não é o dano normal de ficar fora da zona segura.", "aliases": ["surge", "storm surge"], "mode": "both", "scope": "concept", "season": "", "version": "", "region": "", "evidence": "official", "verified_at": "2026-10-11T00:28:00.000Z", "valid_until": "2027-04-10T00:00:00.000Z", "sources": [{"title": "Epic Games · explicação histórica de Storm Surge", "url": "https://www.fortnite.com/news/fortnite-chapter-3-season-3-competitive-storm-surge-update", "kind": "official", "published_on": "2022-07-20"}], "limitations": "A fonte é de 2022 e sustenta o conceito, não números atuais. Limiares, fases e valores exigem verificação do modo e da versão atual.", "related": [{"title": "Explorar habilidades e glossário", "path": "/academy/research"}, {"title": "Biblioteca de exercícios", "path": "/library"}]}'::jsonb,1);
