insert into public.knowledge_drafts(id,payload,published_revision) values('00000000-0000-4000-8000-000000008801','{"subject": "igl", "title": "IGL", "category": "equipe", "body": "IGL (in-game leader) é o integrante que coordena decisões durante a partida, como rotações, posicionamento e escolha de confrontos. A equipe combina responsabilidades; os demais jogadores continuam fornecendo informação e tomando decisões. Exemplo: sinalizar uma rotação e confirmar se todos têm recursos para acompanhá-la.", "aliases": ["igl", "in game leader"], "mode": "both", "scope": "concept", "season": "", "version": "", "region": "", "evidence": "editorial", "verified_at": "2026-10-11T00:28:00.000Z", "valid_until": "2027-04-10T00:00:00.000Z", "sources": [{"title": "kyrven · definições editoriais de conhecimento", "url": "https://github.com/sallumm/fortnite-competitive-platform/blob/feat/fortnite-knowledge/docs/FORTNITE_KNOWLEDGE.md", "kind": "editorial", "published_on": null}], "limitations": "Definição editorial de uma função de equipe; não é cargo oficial nem regra de torneio.", "related": [{"title": "Explorar habilidades e glossário", "path": "/academy/research"}, {"title": "Biblioteca de exercícios", "path": "/library"}]}'::jsonb,1);
