-- Bounded union over the existing Meta corpus. No separate copy of version-specific game data.
create function public.knowledge_editorial(p_query text,p_mode text,p_season text,p_version text,p_region text,p_current boolean default false) returns jsonb language sql stable security definer set search_path='' as $$
 select coalesce(jsonb_agg(jsonb_build_object('id','meta:'||e.id,'revision',e.revision,'origin','meta','payload',jsonb_build_object('subject',e.subject_key,'title',left(e.title,200),'category',e.category,'body',e.body,'aliases',jsonb_build_array(e.title,e.subject_key),'mode',case when m.construction then 'build' else 'zero' end,'scope','season','season',v.season,'version',v.patch,'region',case when c.region='unspecified' then '' else c.region end,'evidence',e.evidence,'verified_at',e.verified_at,'valid_until',e.review_due,'limitations',left(e.limitations,1000),'related','[]'::jsonb,'sources',(select coalesce(jsonb_agg(jsonb_build_object('title',left(s.title,200),'url',s.url,'kind',s.kind,'published_on',s.published_on)),'[]') from public.meta_sources s where s.id=any(e.source_ids))))),'[]')
 from (select * from public.meta_entries me where public.meta_entry_visible(me.id) and me.state in('confirmed','under_analysis') and me.review_due>now() and me.valid_from<=now() and not exists(select 1 from public.meta_entries newer where newer.context_id=me.context_id and newer.subject_key=me.subject_key and newer.revision>me.revision and newer.valid_from<=now()) and exists(select 1 from regexp_split_to_table(p_query,'[[:space:]]+') t where length(t)>=3 and (me.title||' '||me.body) ilike '%'||replace(replace(t,'%','\%'),'_','\_')||'%') order by me.verified_at desc limit 12) e
 join public.meta_contexts c on c.id=e.context_id join public.meta_versions v on v.id=c.version_id join public.meta_modes m on m.id=c.mode_id
 where v.season=p_season and (not p_current or not exists(select 1 from public.meta_contexts newer join public.meta_versions nv on nv.id=newer.version_id where newer.mode_id=c.mode_id and nv.released_on>v.released_on and nv.released_on<=current_date)) and (p_version='' or v.patch=p_version) and (p_region='' or c.region='unspecified' or c.region=p_region) and (p_mode='both' or case when m.construction then 'build' else 'zero' end=p_mode);
$$;
revoke all on function public.knowledge_editorial(text,text,text,text,text,boolean) from public;
grant execute on function public.knowledge_editorial(text,text,text,text,text,boolean) to anon,authenticated;
